<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import Icon from './Icon.vue'
import {ACCENT_PRESETS,normalizeAccent,isAccentColor,hexToHsv,hsvToHex,createAccentPalette} from '../accent-color.mjs'
const props=defineProps<{modelValue:string;disabled?:boolean;textMode?:'auto'|'dark'|'light'}>(),emit=defineEmits<{'update:modelValue':[string]}>()
const picker=ref<HTMLElement>(),trigger=ref<HTMLButtonElement>(),plane=ref<HTMLElement>(),open=ref(false),hexText=ref(''),hue=ref(0),saturation=ref(0),value=ref(0),position=ref({left:'0px',top:'0px'})
const color=computed(()=>normalizeAccent(props.modelValue)),invalidHex=computed(()=>!/^#?[0-9a-f]{6}$/i.test(hexText.value))
watch(color,current=>{hexText.value=current;const hsv=hexToHsv(current);if(hsv.s>0&&hsv.v>0)hue.value=hsv.h;if(hsv.v>0)saturation.value=hsv.s;value.value=hsv.v},{immediate:true})
function setColor(next:string){if(!props.disabled)emit('update:modelValue',normalizeAccent(next))}
function updateHex(){const candidate=hexText.value.startsWith('#')?hexText.value:'#'+hexText.value;if(isAccentColor(candidate))setColor(candidate)}
function updateHsv(){setColor(hsvToHex({h:hue.value,s:saturation.value,v:value.value}))}
function place(){const rect=trigger.value?.getBoundingClientRect();if(!rect)return;const width=Math.min(308,window.innerWidth-24),height=350;position.value={left:`${Math.max(12,Math.min(rect.right-width,window.innerWidth-width-12))}px`,top:`${Math.max(12,rect.bottom+8+height<window.innerHeight?rect.bottom+8:rect.top-height-8)}px`}}
async function toggle(){if(props.disabled)return;if(open.value){picker.value?.hidePopover();return}place();picker.value?.showPopover();await nextTick();picker.value?.querySelector<HTMLElement>('[role=slider]')?.focus()}
function toggled(event:Event){open.value=(event as ToggleEvent).newState==='open';if(!open.value){stopDrag();detachPosition()}else{window.addEventListener('resize',place);window.addEventListener('scroll',place,true)}}
let pointer:number|undefined
function selectPoint(event:PointerEvent){if(props.disabled||pointer!==event.pointerId)return;const rect=plane.value?.getBoundingClientRect();if(!rect)return;saturation.value=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width));value.value=1-Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height));updateHsv()}
function startDrag(event:PointerEvent){if(props.disabled||pointer!==undefined||event.button!==0)return;event.preventDefault();pointer=event.pointerId;plane.value?.setPointerCapture(pointer);selectPoint(event)}
function stopDrag(event?:PointerEvent){if(event&&event.pointerId!==pointer)return;const id=pointer;pointer=undefined;if(id!==undefined&&plane.value?.hasPointerCapture(id))plane.value.releasePointerCapture(id)}
function detachPosition(){window.removeEventListener('resize',place);window.removeEventListener('scroll',place,true)}
function planeKey(event:KeyboardEvent){if(props.disabled||event.altKey||event.ctrlKey||event.metaKey)return;const step=event.shiftKey?.1:.01;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();if(event.key==='Home')saturation.value=0;else if(event.key==='End')saturation.value=1;else if(event.key==='ArrowLeft')saturation.value=Math.max(0,saturation.value-step);else if(event.key==='ArrowRight')saturation.value=Math.min(1,saturation.value+step);else if(event.key==='ArrowUp')value.value=Math.min(1,value.value+step);else value.value=Math.max(0,value.value-step);updateHsv()}
function presetKey(event:KeyboardEvent,index:number){if(props.disabled||event.altKey||event.ctrlKey||event.metaKey)return;const next=event.key==='ArrowRight'?index+1:event.key==='ArrowLeft'?index-1:event.key==='Home'?0:event.key==='End'?ACCENT_PRESETS.length-1:undefined;if(next===undefined)return;event.preventDefault();const actual=(next+ACCENT_PRESETS.length)%ACCENT_PRESETS.length;setColor(ACCENT_PRESETS[actual].value);(event.currentTarget as HTMLElement).parentElement?.querySelectorAll<HTMLButtonElement>('[role=radio]')[actual]?.focus()}
watch(()=>props.disabled,disabled=>{if(disabled){stopDrag();picker.value?.hidePopover()}})
onBeforeUnmount(()=>{stopDrag();detachPosition()})
</script>
<template>
 <div class="accent-picker">
  <div class="accent-presets" role="radiogroup" aria-label="强调色预设"><button v-for="(preset,index) in ACCENT_PRESETS" :key="preset.value" type="button" role="radio" :aria-label="preset.label" :aria-checked="color===preset.value" :tabindex="color===preset.value||(!ACCENT_PRESETS.some(item=>item.value===color)&&index===0)?0:-1" :disabled="disabled" :style="{'--swatch':preset.value,'--swatch-ink':createAccentPalette(preset.value,false,textMode)['--on-accent']}" @click="setColor(preset.value)" @keydown="presetKey($event,index)"><span/><Icon v-if="color===preset.value" name="check" :size="16"/></button></div>
  <button ref="trigger" type="button" class="custom-color-button" :aria-expanded="open" :disabled="disabled" @click="toggle"><span :style="{background:color}"/><span>自定义</span><Icon name="down" :size="14"/></button>
  <div ref="picker" popover="auto" class="color-popover" :style="position" @toggle="toggled">
   <h4>自定义强调色</h4>
   <div ref="plane" class="color-plane" role="slider" tabindex="0" aria-label="饱和度与明度；左右调整饱和度，上下调整明度" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="Math.round(saturation*100)" :aria-valuetext="`饱和度 ${Math.round(saturation*100)}%，明度 ${Math.round(value*100)}%`" :style="{backgroundColor:`hsl(${hue} 100% 50%)`}" @pointerdown="startDrag" @pointermove="selectPoint" @pointerup="stopDrag" @pointercancel="stopDrag" @lostpointercapture="stopDrag" @keydown="planeKey"><span class="color-point" :style="{left:`${saturation*100}%`,top:`${(1-value)*100}%`,background:color}"/></div>
   <label class="hue-control"><span>色相</span><input v-model.number="hue" type="range" min="0" max="360" step="1" aria-label="色相" :disabled="disabled" @input="updateHsv"/></label>
   <label class="hex-control"><span>HEX</span><input v-model="hexText" type="text" maxlength="7" aria-label="自定义强调色 HEX" :aria-invalid="invalidHex||undefined" spellcheck="false" autocomplete="off" :disabled="disabled" @input="updateHex" @keydown.enter.prevent="updateHex"/></label>
   <p v-if="invalidHex" class="color-error" role="status">输入 6 位十六进制颜色</p>
  </div>
 </div>
</template>
<style scoped>
.accent-picker{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:8px;min-width:0}.accent-presets{display:flex;flex-wrap:wrap;gap:4px}.accent-presets button{width:32px;height:36px;display:grid;place-items:center;position:relative;border:0;border-radius:8px;padding:0;outline:none}.accent-presets button>span{width:24px;height:24px;border-radius:50%;background:var(--swatch);border:1px solid #0002}.accent-presets button>svg{position:absolute;color:var(--swatch-ink)}.accent-presets button[aria-checked=true],.accent-presets button:focus-visible{background:var(--sand-bg-hover);text-decoration:none;outline-offset:1px}.custom-color-button{display:flex;align-items:center;gap:8px;min-height:36px;border-radius:8px;padding:4px 8px;background:var(--sand-bg-secondary);font-size:13px}.custom-color-button>span:first-child{width:16px;height:16px;border-radius:50%;border:1px solid var(--sand-border-quaternary-translucent)}.color-popover{position:fixed;inset:auto;margin:0;width:min(308px,calc(100vw - 24px));padding:16px;border:1px solid var(--sand-border-quaternary-translucent);border-radius:12px;background:var(--sand-bg-elevated);color:var(--sand-text-primary);box-shadow:0 8px 24px #0002;max-height:calc(100dvh - 24px);overflow:auto}.color-popover h4{font-size:13px;font-weight:420;margin:0 0 12px}.color-plane{height:168px;border-radius:8px;position:relative;touch-action:none;background-image:linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,transparent);cursor:crosshair;outline:none}.color-plane:focus-visible{filter:brightness(.96)}.color-point{position:absolute;width:14px;height:14px;transform:translate(-50%,-50%);border-radius:50%;border:2px solid white;box-shadow:0 1px 3px #0008;pointer-events:none}.hue-control,.hex-control{display:flex;align-items:center;gap:12px;font-size:13px;margin-top:16px}.hue-control>span,.hex-control>span{width:36px;flex:none}.hue-control input{appearance:none;min-width:0;width:100%;height:24px;background:transparent;padding:0;outline:none}.hue-control input::-webkit-slider-runnable-track{height:10px;border-radius:8px;background:linear-gradient(to right,red,#ff0,#0f0,#0ff,#00f,#f0f,red)}.hue-control input::-webkit-slider-thumb{appearance:none;width:16px;height:16px;margin-top:-3px;border:2px solid white;border-radius:50%;background:hsl(v-bind(hue) 100% 50%);box-shadow:0 1px 3px #0006}.hex-control input{min-width:0;width:100%;min-height:40px;padding:4px 8px;background:var(--sand-bg-secondary);border:1px solid var(--sand-border-quaternary-translucent);border-radius:8px;font-size:13px;outline:none;box-shadow:none;height:28px;min-height:28px;box-sizing:border-box}.color-error{font-size:13px;color:var(--sand-text-danger-primary);margin:8px 0 0}@media(max-width:600px){.accent-presets button{width:44px;height:28px}.custom-color-button{min-height:28px}.accent-presets{max-width:188px}}
</style>

